tool_input.new_string:
            });
        }
        let invalid = extract_invalid_chars(input, is_identifier_char);
        if !invalid.is_empty() {
            return Err(ParseError::InvalidCharacters {
                type_name: TYPE_NAME,
                invalid_chars: invalid,
            });
        }
        Ok(Self(input.to_string()))
    }

    #[must_use]
    pub fn as_str(&self) -> &str {
        &self.0
    }
}
